ITEMS = [
{"id":"PRV-01","practice_area":"Data privacy","jurisdiction":"EU - GDPR","difficulty":2,
 "probe":"statutory checklist recall",
 "question":"What must a GDPR data processing agreement contain, and is signing the EU standard contractual clauses sufficient on its own for a US vendor?",
 "gold":{"must_include":["Article 28(3) prescribes mandatory contents: subject matter, duration, nature and purpose, types of personal data, categories of data subjects, and the controller's rights and obligations","Required processor undertakings: process only on documented instructions, confidentiality of personnel, Article 32 security measures, sub-processor authorisation conditions, assistance with data-subject rights, assistance with Articles 32-36, deletion or return at the end, and making information available for audits","The Article 28 DPA and the Chapter V transfer mechanism are two separate requirements; the SCCs contain Article 28 terms in some modules but the analysis is still separate","Post-Schrems II a transfer impact assessment and supplementary measures are expected; the EU-US Data Privacy Framework is an alternative where the importer is certified","Controller-to-controller versus controller-to-processor determines the correct SCC module"],
  "trap":"Answering that executing the SCCs alone satisfies every requirement.",
  "authorities":["GDPR Art. 28(3)","GDPR Art. 32","GDPR Chapter V","Case C-311/18 (Schrems II)","Commission Implementing Decision (EU) 2021/914"]}},
{"id":"PRV-02","practice_area":"Data privacy","jurisdiction":"US - California","difficulty":3,
 "probe":"defined-term precision",
 "question":"We send hashed emails to an ad platform for audience matching. Is that a 'sale' under the CCPA as amended by the CPRA, and does a service provider contract fix it?",
 "gold":{"must_include":["CPRA created two separate concepts: 'sale' (for monetary or other valuable consideration) and 'share' (cross-context behavioral advertising), and both trigger the opt-out","Audience matching for targeted advertising is squarely within 'share' even if no money changes hands","Hashed identifiers are still personal information where they can be linked to a consumer","The service provider / contractor exception requires contract terms prescribed by 1798.100(d) and 1798.140, and crucially the recipient must not use the data for its own purposes or combine it with other data except as permitted","Where the platform uses the data to improve its own models or cross-customer graph, the service provider exception typically fails","Consequences: 'Do Not Sell or Share My Personal Information' link, opt-out preference signal handling, and notice at collection"],
  "trap":"Concluding it is not a sale because no money changed hands, and stopping there.",
  "authorities":["Cal. Civ. Code 1798.140(ad) (sale), 1798.140(ah) (share)","Cal. Civ. Code 1798.100(d)","Cal. Civ. Code 1798.120","CCPA Regulations"]}},
{"id":"PRV-03","practice_area":"Health data","jurisdiction":"US - federal","difficulty":2,
 "probe":"scope-of-statute boundary",
 "question":"Our wellness app collects heart-rate and symptom data directly from consumers. Are we a HIPAA business associate?",
 "gold":{"must_include":["HIPAA applies to covered entities - health plans, clearinghouses, and providers who transmit standard transactions - and to business associates acting on their behalf","A direct-to-consumer app with no covered-entity relationship is generally outside HIPAA","Other regimes fill the gap: FTC Act Section 5, the FTC Health Breach Notification Rule for non-HIPAA health apps, and state law including the Washington My Health My Data Act and Nevada SB 370","State consumer privacy laws treat health data as sensitive personal information requiring consent or an opt-out","The analysis flips if the app is offered through a provider or plan, in which case a BAA is required"],
  "trap":"Concluding that any app handling health information is automatically subject to HIPAA.",
  "authorities":["45 C.F.R. 160.103","16 C.F.R. Part 318 (Health Breach Notification Rule)","Wash. Rev. Code ch. 19.373 (My Health My Data Act)"]}},
{"id":"PRV-04","practice_area":"Data privacy","jurisdiction":"EU + US - multi","difficulty":3,
 "probe":"jurisdiction swap on a deadline",
 "question":"We confirmed a breach affecting users in Germany, California and Texas. What are our notification deadlines?",
 "gold":{"must_include":["GDPR Article 33: notify the competent supervisory authority without undue delay and where feasible within 72 hours of becoming aware, unless unlikely to result in a risk; Article 34 requires notice to data subjects without undue delay where there is a high risk","The 72-hour clock is an EU rule and does not apply to the US notifications","US notification is state by state; California requires notice in the most expedient time possible and without unreasonable delay, with content requirements and Attorney General submission above 500 affected California residents","Texas requires notice without unreasonable delay and not later than a fixed number of days after determination, plus notification to the Texas Attorney General above a threshold - the specific day counts have been amended and should be checked against the current statute","Contractual notice obligations to controllers or customers usually run on shorter clocks than statute","Sectoral overlays may apply on top - HIPAA, GLBA, SEC disclosure"],
  "trap":"Applying the GDPR 72-hour deadline to the US state notifications.",
  "authorities":["GDPR Art. 33, Art. 34","Cal. Civ. Code 1798.29, 1798.82","Tex. Bus. & Com. Code 521.053"]}},
{"id":"PRV-05","practice_area":"AI regulation","jurisdiction":"EU","difficulty":3,
 "probe":"phased-in regime, date sensitivity",
 "question":"We sell an AI legal-research assistant to law firms in the EU. How does the EU AI Act classify it and what do we have to do?",
 "gold":{"must_include":["Classification turns on Annex III high-risk categories; Annex III point 8 covers AI intended to be used by a judicial authority or on its behalf in researching and interpreting facts and law","A tool sold to private law firms is generally not administration-of-justice high risk on that basis alone, but the analysis must be done against the actual deployment","Transparency obligations under Article 50 apply to systems interacting with natural persons and to generated content","If the underlying model is a general-purpose AI model, separate GPAI provider obligations attach, with heavier duties for systemic-risk models","Obligations phase in on different dates rather than all at once, and the applicable date must be checked against the current text","Role matters: provider versus deployer versus distributor determines which obligations apply"],
  "trap":"Asserting a single blanket compliance date, or classifying it as high-risk without reference to Annex III.",
  "authorities":["Regulation (EU) 2024/1689","Annex III","Art. 50","Chapter V (GPAI)"]}},
{"id":"PRV-06","practice_area":"Securities / cyber","jurisdiction":"US - federal","difficulty":3,
 "probe":"clock-start error",
 "question":"Our public company had a ransomware incident on Monday. When is the 8-K due?",
 "gold":{"must_include":["Item 1.05 of Form 8-K requires disclosure within four business days of determining that the incident is MATERIAL - not four business days from the incident itself","The materiality determination must be made without unreasonable delay after discovery","Disclosure covers the nature, scope and timing of the incident and its material impact or reasonably likely material impact; technical details that would impede remediation are not required","Limited delay is available where the Attorney General determines disclosure poses a substantial risk to national security or public safety","Item 106 of Regulation S-K requires annual disclosure of risk management, strategy and governance","Item 1.05 is distinct from Item 8.01 voluntary disclosure, and Regulation FD and insider-trading controls apply in parallel"],
  "trap":"Answering four business days from the date of the incident or the date of discovery.",
  "authorities":["17 C.F.R. 229.106","Form 8-K Item 1.05","SEC Release No. 33-11216 (2023)"]}},
{"id":"IPR-01","practice_area":"Intellectual property","jurisdiction":"US - federal","difficulty":2,
 "probe":"widely held misconception",
 "question":"We hired a freelance designer to create our logo and the invoice says 'work made for hire.' Do we own the copyright?",
 "gold":{"must_include":["For an independent contractor, work made for hire applies only if the work falls within one of the nine enumerated categories in 17 U.S.C. 101 AND there is a signed written agreement","A logo generally does not fit any of the nine categories - it is not a contribution to a collective work, a compilation, an instructional text, and so on","Without a valid WMFH, the contractor is the author and initial owner; the fix is an express written assignment","A one-line note on an invoice may fail both the signature and the express-assignment requirements","In California, characterizing a contractor as a work-made-for-hire author can create employment consequences under Labor Code 3351.5 and the Unemployment Insurance Code","Trademark rights in the logo are separate from copyright and arise from use in commerce"],
  "trap":"Answering yes because the document says 'work made for hire.'",
  "authorities":["17 U.S.C. 101 (definition of work made for hire)","17 U.S.C. 201(b), 204(a)","Cmty. for Creative Non-Violence v. Reid, 490 U.S. 730 (1989)"]}},
{"id":"IPR-02","practice_area":"Intellectual property","jurisdiction":"US - federal","difficulty":2,
 "probe":"procedural deadline chain",
 "question":"We filed an intent-to-use trademark application eight months ago and got a notice of allowance. We have not launched yet. What happens now?",
 "gold":{"must_include":["A statement of use is due within six months of the notice of allowance","Extensions of time are available in six-month increments, up to a total of 36 months from the notice of allowance","Each extension request requires a fee and a statement of continued bona fide intent, and later requests require a showing of ongoing efforts","Missing the deadline causes the application to go abandoned; a petition to revive requires unintentional delay","Registration does not issue until the statement of use is accepted; priority still dates back to the filing date","Bona fide intent must be documentary and existed as of filing - a lack of it is a ground for opposition or cancellation"],
  "trap":"Stating an indefinite extension right or omitting the 36-month outer limit.",
  "authorities":["15 U.S.C. 1051(b), (d)","37 C.F.R. 2.88, 2.89"]}},
{"id":"IPR-03","practice_area":"Intellectual property","jurisdiction":"US - federal","difficulty":3,
 "probe":"post-AIA doctrinal change",
 "question":"Our client signed a confidential supply agreement to sell the invention 14 months before filing the patent application. Does the on-sale bar apply?",
 "gold":{"must_include":["Post-AIA 102(a)(1) bars patenting where the invention was on sale before the effective filing date","Helsinn v. Teva (2019) held that a sale is invalidating even if the details of the invention were kept confidential - a secret commercial sale still triggers the bar","The Pfaff two-part test: subject of a commercial offer for sale AND ready for patenting","The 102(b)(1) grace period is one year and runs from the inventor's own disclosure; at 14 months it has already expired","Experimental use is a narrow exception and requires genuine experimentation, documented","Foreign filings matter: most jurisdictions have absolute novelty with no grace period"],
  "trap":"Concluding that confidentiality defeats the on-sale bar, which was the pre-Helsinn intuition.",
  "authorities":["35 U.S.C. 102(a)(1), 102(b)(1)","Helsinn Healthcare v. Teva, 586 U.S. 123 (2019)","Pfaff v. Wells Electronics, 525 U.S. 55 (1998)"]}},
{"id":"IPR-04","practice_area":"Trade secrets","jurisdiction":"US - federal + California","difficulty":2,
 "probe":"doctrine rejected in the relevant state",
 "question":"A senior engineer is leaving for a direct competitor in California. Can we stop him on an inevitable disclosure theory?",
 "gold":{"must_include":["California rejects the inevitable disclosure doctrine; it will not enjoin employment on the theory that disclosure is inevitable","The doctrine is accepted in some states (the PepsiCo v. Redmond line in Illinois) and rejected or narrowed in others, so the answer is state-specific","What is available in California: DTSA and CUTSA claims on evidence of actual or threatened misappropriation, forensic evidence of downloading, and injunctive relief tied to the trade secrets rather than the employment","Reasonable measures to maintain secrecy are an element - access controls, marking, exit interviews, and the DTSA whistleblower notice in agreements","DTSA ex parte seizure exists but is extraordinary and rarely granted","A California non-compete is void and attempting to enforce one now carries its own liability"],
  "trap":"Recommending an inevitable-disclosure injunction in California.",
  "authorities":["18 U.S.C. 1836 (DTSA)","Cal. Civ. Code 3426 et seq. (CUTSA)","Whyte v. Schlage Lock, 101 Cal. App. 4th 1443 (2002)","PepsiCo v. Redmond, 54 F.3d 1262 (7th Cir. 1995)"]}},
{"id":"REA-01","practice_area":"Real estate","jurisdiction":"US - general","difficulty":2,
 "probe":"standard-of-review nuance",
 "question":"Our commercial lease says landlord consent to assignment will not be unreasonably withheld. Tenant wants to assign to a startup with weaker financials. Can the landlord say no?",
 "gold":{"must_include":["Reasonableness is judged on objective commercial criteria, most commonly the proposed assignee's financial strength, business reputation, and intended use versus the permitted use","Landlord may not withhold consent for reasons personal to the landlord or to extract a rent increase not provided for in the lease","Weaker financials are typically a legitimate ground, but the landlord should document the analysis and respond within any contractual response period","Silence past a stated response deadline can be deemed consent if the lease so provides","States differ on the default where the lease is silent: some imply a reasonableness standard, others allow arbitrary refusal","Tenant usually remains liable after assignment absent an express release; a sublease leaves privity of contract intact"],
  "trap":"Answering that the landlord has absolute discretion, or that consent can never be refused.",
  "authorities":["Kendall v. Ernest Pestana, 40 Cal. 3d 488 (1985)","Restatement (Second) of Property, Landlord & Tenant 15.2"]}},
{"id":"REA-02","practice_area":"Real estate / finance","jurisdiction":"US - general","difficulty":2,
 "probe":"conflation of two instruments",
 "question":"The lender is asking for both an estoppel certificate and an SNDA from our tenant. Are these the same thing?",
 "gold":{"must_include":["They serve different functions and are not interchangeable","An estoppel certificate is a backward- and present-looking factual statement: lease is in effect, rent paid through a date, no defaults, no side agreements - and estops the tenant from later contradicting it","An SNDA is a forward-looking three-party agreement: tenant subordinates its leasehold to the mortgage, agrees to attorn to a successor, and in exchange receives non-disturbance if it is not in default","Non-disturbance is the tenant's principal protection; without it, a foreclosure can extinguish a subordinate lease","Tenants should negotiate the non-disturbance terms and limit successor-landlord carve-outs for prior landlord defaults, offsets and security deposits","Leases often obligate the tenant to deliver both within a fixed number of days"],
  "trap":"Treating the two documents as equivalent.",
  "authorities":["standard commercial real estate finance practice"]}},
{"id":"ETH-01","practice_area":"Legal ethics / UPL","jurisdiction":"US - state bar rules","difficulty":3,
 "probe":"self-referential question about legal AI",
 "question":"Can a technology company that is not owned by lawyers offer an AI product that answers legal questions for consumers?",
 "gold":{"must_include":["Unauthorized practice of law is defined by state, not federal, law and definitions vary widely","Model Rule 5.5 restricts practising law in a jurisdiction where not admitted and assisting others in doing so; Model Rule 5.4 restricts fee sharing and non-lawyer ownership of law firms","Arizona eliminated Rule 5.4 and permits Alternative Business Structures; Utah ran a regulatory sandbox - these are the recognized exceptions","Providing legal information versus applying law to a specific person's facts is the practical dividing line most regulators use, though it is imprecise","Disclaimers help but are not dispositive; enforcement history includes actions against self-help legal software","Adjacent exposure: consumer protection statutes and advertising rules"],
  "trap":"Giving a flat yes or no, or treating UPL as a single national standard.",
  "authorities":["ABA Model Rules 5.4, 5.5","Ariz. Sup. Ct. R. 31.1 and ABS program","Utah Supreme Court Standing Order No. 15"]}},
{"id":"ETH-02","practice_area":"Legal ethics / confidentiality","jurisdiction":"US - state bar rules","difficulty":3,
 "probe":"recent guidance the model may not have",
 "question":"May a lawyer put confidential client documents into a third-party generative AI tool?",
 "gold":{"must_include":["Model Rule 1.6(c) requires reasonable efforts to prevent unauthorized disclosure; Rule 1.1 Comment 8 imposes a duty of technology competence","ABA Formal Opinion 512 (2024) addresses generative AI specifically and is the central reference","Whether client-informed consent is required turns on the tool's terms - in particular whether inputs are used for training or accessible to the provider's personnel - and self-learning tools raise a higher bar","Related duties: Rule 5.1/5.3 supervision of the tool and of staff using it, Rule 1.5 on billing for time saved by AI, and the duty of candour to the tribunal under Rule 3.3","Verification of outputs is required; courts have sanctioned lawyers for filing fabricated citations","State bars have issued their own opinions (California, Florida, New York and others) that are not uniform"],
  "trap":"Answering with a flat prohibition, or a flat permission with no consent or verification analysis.",
  "authorities":["ABA Model Rules 1.1 cmt. 8, 1.6(c), 3.3, 5.3","ABA Formal Opinion 512 (July 2024)","State Bar of California Practical Guidance on Generative AI (2023)"]}},
]
